      encryptedMinimaxApiKey:
        typeof data?.encryptedMinimaxApiKey === "string" ? data.encryptedMinimaxApiKey : null,
      authMethod:
        data?.authMethod === "api_key" || data?.authMethod === "claude_login"
          ? data.authMethod
          : "claude_login",
    };
  } catch {
    return { ...DEFAULT_CONFIG };
  }
}

