export async function checkCliLogin(): Promise<{ loggedIn: boolean; email?: string }> {
  try {
    const { execFile } = await import("node:child_process");
    const { promisify } = await import("node:util");
    const execFileAsync = promisify(execFile);
    const { stdout } = await execFileAsync("claude", ["auth", "status"], {
      timeout: 5000,
      env: process.env,
    });
    const parsed = JSON.parse(stdout.trim());
    return {
      loggedIn: parsed.loggedIn === true,
      email: parsed.email ?? undefined,
    };
  } catch {
    return { loggedIn: false };
  }
}

import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { mkdtempSync, rmSync, writeFileSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { execSync } from "node:child_process";
import { gitService } from "./git-service";

describe("GitService checkpoint (stash) operations", () => {
  let tmpDir: string;

  function runGit(cwd: string, args: string[]) {
    execSync(`git ${args.join(" ")}`, { cwd, encoding: "utf-8" });
  }

  beforeEach(() => {
    tmpDir = mkdtempSync(join(tmpdir(), "git-service-test-"));
    runGit(tmpDir, ["init"]);
    runGit(tmpDir, ["config", "user.email", "test@test.com"]);
    runGit(tmpDir, ["config", "user.name", "Test"]);
  });

  afterEach(() => {
    rmSync(tmpDir, { recursive: true, force: true });
  });

  describe("hasChanges", () => {
    it("returns false for clean working tree", async () => {
      const result = await gitService.hasChanges(tmpDir);
      expect(result).toBe(false);
    });

    it("returns true when there are unstaged changes", async () => {
      writeFileSync(join(tmpDir, "file.txt"), "hello");
      const result = await gitService.hasChanges(tmpDir);
      expect(result).toBe(true);
    });

    it("returns true when there are staged changes", async () => {
      writeFileSync(join(tmpDir, "file.txt"), "hello");
      runGit(tmpDir, ["add", "file.txt"]);
      const result = await gitService.hasChanges(tmpDir);
      expect(result).toBe(true);
    });
  });

  describe("stashCreate", () => {
    it("returns a non-empty ref when there are uncommitted changes", async () => {
      writeFileSync(join(tmpDir, "file.txt"), "original");
      runGit(tmpDir, ["add", "file.txt"]);
      runGit(tmpDir, ["commit", "-m", "initial"]);
      writeFileSync(join(tmpDir, "file.txt"), "modified");

      const ref = await gitService.stashCreate(tmpDir);
      expect(ref).toBeTruthy();
      expect(typeof ref).toBe("string");
      expect(ref!.length).toBeGreaterThan(0);
    });

    it("returns null when there are no changes", async () => {
      writeFileSync(join(tmpDir, "file.txt"), "content");
      runGit(tmpDir, ["add", "file.txt"]);
      runGit(tmpDir, ["commit", "-m", "initial"]);

      const ref = await gitService.stashCreate(tmpDir);
      expect(ref).toBeNull();
    });

    it("returns null or throws when not a git repo", async () => {
      const notRepo = mkdtempSync(join(tmpdir(), "not-repo-"));
      try {
        const ref = await gitService.stashCreate(notRepo);
        expect(ref).toBeNull();
      } catch {
        // allowed to throw
      } finally {
        rmSync(notRepo, { recursive: true, force: true });
      }
    });
  });

  describe("stashApply", () => {
    it("restores working tree from stash ref", async () => {
      writeFileSync(join(tmpDir, "file.txt"), "original");
      runGit(tmpDir, ["add", "file.txt"]);
      runGit(tmpDir, ["commit", "-m", "initial"]);
      writeFileSync(join(tmpDir, "file.txt"), "modified");

      const ref = await gitService.stashCreate(tmpDir);
      expect(ref).toBeTruthy();

      writeFileSync(join(tmpDir, "file.txt"), "changed again");
      await gitService.stashApply(tmpDir, ref!);

      const content = readFileSync(join(tmpDir, "file.txt"), "utf-8");
      expect(content.trim()).toBe("modified");
    });

    it("throws on invalid ref", async () => {
      await expect(
        gitService.stashApply(tmpDir, "invalid-ref-000000")
      ).rejects.toThrow();
    });
  });
});

import path from "node:path";
import { existsSync, readFileSync } from "node:fs";
import { mkdir, rename, unlink } from "node:fs/promises";
import { simpleGit, type SimpleGit, type StatusResult } from "simple-git";

export type GitBranch = {
  name: string;
  current: boolean;
  remote?: string;
};

export class GitService {
  private getGit(cwd: string): SimpleGit {
    return simpleGit(cwd);
  }

  async isGitRepository(workspacePath: string): Promise<boolean> {
    try {
      const gitDir = path.join(workspacePath, ".git");
      if (!existsSync(gitDir)) return false;
      const git = this.getGit(workspacePath);
      await git.revparse(["--git-dir"]);
      return true;
    } catch {
      return false;
    }
  }

  async getCurrentBranch(workspacePath: string): Promise<string | null> {
    try {
      const git = this.getGit(workspacePath);
      const status = await git.status();
      return status.current ?? null;
    } catch {
      return null;
    }
  }

  async getAllBranches(workspacePath: string): Promise<GitBranch[]> {
    try {
      const git = this.getGit(workspacePath);
      const branchSummary = await git.branch(["-a"]);
      const branches: GitBranch[] = [];

      for (const [name, branch] of Object.entries(branchSummary.branches)) {
        if (name.includes("HEAD ->")) continue;

        let branchName = name;
        let remote: string | undefined;

        if (name.startsWith("remotes/")) {
          const parts = name.replace("remotes/", "").split("/");
          if (parts.length >= 2) {
            remote = parts[0];
            branchName = parts.slice(1).join("/");
          }
        }

        const existing = branches.find((b) => b.name === branchName);
        if (existing) {
          if (!existing.remote && remote) existing.remote = remote;
        } else {
          branches.push({
            name: branchName,
            current: branch.current,
            remote,
          });
        }
      }

      return branches;
    } catch (error) {
      throw new Error(
        `Failed to get branches: ${error instanceof Error ? error.message : "Unknown error"}`
      );
    }
  }

  async switchBranch(workspacePath: string, branchName: string): Promise<void> {
    try {
      const git = this.getGit(workspacePath);
      await git.checkout(branchName);
    } catch (error) {
      throw new Error(
        `Failed to switch to branch ${branchName}: ${error instanceof Error ? error.message : "Unknown error"}`
      );
    }
  }

  async createAndSwitchBranch(workspacePath: string, branchName: string): Promise<void> {
    try {
      const git = this.getGit(workspacePath);
      await git.checkoutLocalBranch(branchName);
    } catch (error) {
      throw new Error(
        `Failed to create and switch to branch ${branchName}: ${error instanceof Error ? error.message : "Unknown error"}`
      );
    }
  }

  async getUnstagedNumstat(
    workspacePath: string
  ): Promise<{ path: string; added: number; deleted: number }[]> {
    try {
      const git = this.getGit(workspacePath);
      const [status, diffSummary] = await Promise.all([
        git.status(),
        git.diffSummary().catch(() => ({ files: [] })),
      ]);

      const numstatMap = new Map<string, { added: number; deleted: number }>();
      for (const file of diffSummary.files) {
        if (!file.binary) {
          numstatMap.set(file.file, {
            added: file.insertions,
            deleted: file.deletions,
          });
        }
      }

async getUnstagedNumstat(
  workspacePath: string
): Promise<{ path: string; added: number; deleted: number }[]> {
  try {
    const git = this.getGit(workspacePath);
    const [status, diffSummary] = await Promise.all([
      git.status(),
      git.diffSummary().catch(() => ({ files: [] })),
    ]);

    const numstatMap = new Map<string, { added: number; deleted: number }>();
    for (const file of diffSummary.files) {
      if (!file.binary) {
        numstatMap.set(file.file, {
          added: file.insertions,
          deleted: file.deletions,
        });
      }
    }

    const result: { path: string; added: number; deleted: number }[] = [];
    for (const file of status.files) {
      if (file.working_dir === " " || file.working_dir === "?") {
        if (file.working_dir !== "?") continue;
      }
      if (file.working_dir === " ") continue;

      const filePath = file.path;
      if (filePath.endsWith("/")) continue;

      const counts = numstatMap.get(filePath);
      result.push({
        path: filePath,
        added: counts?.added ?? 0,
        deleted: counts?.deleted ?? 0,
      });
    }

    return result;
  } catch (error) {
    throw new Error(
      `Failed to get unstaged changes: ${error instanceof Error ? error.message : "Unknown"}`
    );
  }
}

async getStagedNumstat(
  workspacePath: string
): Promise<{ path: string; added: number; deleted: number }[]> {
  try {
    const git = this.getGit(workspacePath);
    const [status, diffSummary] = await Promise.all([
      git.status(),
      git.diffSummary(["--cached"]).catch(() => ({ files: [] })),
    ]);

    const numstatMap = new Map<string, { added: number; deleted: number }>();
    for (const file of diffSummary.files) {
      if (!file.binary) {
        numstatMap.set(file.file, {
          added: file.insertions,
          deleted: file.deletions,
        });
      }
    }

    const result: { path: string; added: number; deleted: number }[] = [];
    for (const file of status.files) {
      if (file.index === " " || file.index === "?") continue;

      const filePath = file.path;
      if (filePath.endsWith("/")) continue;

      const counts = numstatMap.get(filePath);
      result.push({
        path: filePath,
        added: counts?.added ?? 0,
        deleted: counts?.deleted ?? 0,
      });
    }

    return result;
  } catch (error) {
    throw new Error(
      `Failed to get staged changes: ${error instanceof Error ? error.message : "Unknown"}`
    );
  }
}

