import type { IPty } from "node-pty";
import * as pty from "node-pty";
import os from "node:os";
import path from "node:path";

const isWindows = process.platform === "win32";
const shell = process.env[isWindows ? "COMSPEC" : "SHELL"] || (isWindows ? "cmd.exe" : "/bin/bash");
const defaultCwd = process.env.HOME || process.env.USERPROFILE || path.resolve("/");

const terminals = new Map<string, IPty>();

export type CreateTerminalParams = {
  cwd?: string;
  cols?: number;
  rows?: number;
};

export function createTerminal(params: CreateTerminalParams): { terminalId: string; pty: IPty } {
  const terminalId = `term-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
  const cwd = params.cwd || defaultCwd;
  const cols = params.cols ?? 80;
  const rows = params.rows ?? 24;

  const ptyProcess = pty.spawn(shell, [], {
    name: "xterm-256color",
    cols,
    rows,
    cwd,
    env: { ...process.env },
  });

  terminals.set(terminalId, ptyProcess);
  return { terminalId, pty: ptyProcess };
}

export function writeToTerminal(terminalId: string, data: string): boolean {
  const p = terminals.get(terminalId);
  if (!p) return false;
  p.write(data);
  return true;
}

export function resizeTerminal(terminalId: string, cols: number, rows: number): boolean {
  const p = terminals.get(terminalId);
  if (!p) return false;
  p.resize(cols, rows);
  return true;
}

export function destroyTerminal(terminalId: string): boolean {
  const p = terminals.get(terminalId);
  if (!p) return false;
  p.kill();
  terminals.delete(terminalId);
  return true;
}

export function getTerminal(terminalId: string): IPty | undefined {
  return terminals.get(terminalId);
}

export function removeTerminal(terminalId: string): void {
  terminals.delete(terminalId);
}

import { watch } from "node:fs";
import { existsSync } from "node:fs";
import path from "node:path";
import { spawn } from "node:child_process";
import { IPC } from "@agentide/shared";

const DEBOUNCE_MS = 350;
const GIT_DEBOUNCE_MS = 300;
const GIT_POLL_INTERVAL_MS = 2500;

type Send = (channel: string, payload: { workspaceId: string }) => void;

type State = {
  workspaceId: string;
  workspacePath: string;
  fileWatcher: ReturnType<typeof watch> | null;
  fileDebounceTimer: ReturnType<typeof setTimeout> | null;
  gitIndexWatcher: ReturnType<typeof watch> | null;
  gitDebounceTimer: ReturnType<typeof setTimeout> | null;
  gitPollTimer: ReturnType<typeof setInterval> | null;
  lastGitStatus: string | null;
};

let state: State | null = null;
let send: Send | null = null;

function runGitStatus(cwd: string): Promise<string> {
  return new Promise((resolve, reject) => {
    const proc = spawn("git", ["status", "--porcelain"], {
      cwd,
      stdio: ["pipe", "pipe", "pipe"],
      shell: process.platform === "win32",
    });
    let out = "";
    let err = "";
    proc.stdout?.on("data", (d) => (out += d.toString()));
    proc.stderr?.on("data", (d) => (err += d.toString()));
    proc.on("close", (code) => {
      if (code === 0) resolve(out);
      else reject(new Error(err || `git status exited ${code}`));
    });
    proc.on("error", reject);
  });
}

function stopFileWatcher(): void {
  if (state?.fileWatcher) {
    try {
      state.fileWatcher.close();
    } catch {
      // ignore
    }
    state.fileWatcher = null;
  }
  if (state?.fileDebounceTimer) {
    clearTimeout(state.fileDebounceTimer);
    state.fileDebounceTimer = null;
  }
}

function stopGitIndexWatcher(): void {
  if (state?.gitIndexWatcher) {
    try {
      state.gitIndexWatcher.close();
    } catch {
      // ignore
    }
    state.gitIndexWatcher = null;
  }
  if (state?.gitDebounceTimer) {
    clearTimeout(state.gitDebounceTimer);
    state.gitDebounceTimer = null;
  }
}

function stopGitPoller(): void {
  if (state?.gitPollTimer) {
    clearInterval(state.gitPollTimer);
    state.gitPollTimer = null;
  }
  state && (state.lastGitStatus = null);
}

function emitFilesChanged(workspaceId: string): void {
  if (state?.fileDebounceTimer) clearTimeout(state.fileDebounceTimer);
  state!.fileDebounceTimer = setTimeout(() => {
    state!.fileDebounceTimer = null;
    send?.(IPC.WORKSPACE_FILES_CHANGED, { workspaceId });
  }, DEBOUNCE_MS);
}

function startFileWatcher(workspaceId: string, workspacePath: string): void {
  if (!existsSync(workspacePath)) return;
  try {
    const watcher = watch(
      workspacePath,
      { recursive: process.platform !== "linux" },
      (eventType, filename) => {
        if (filename && (filename as string).includes(".git")) return;
        emitFilesChanged(workspaceId);
      }
    );
    state!.fileWatcher = watcher;
  } catch {
    // ignore
  }
}

function emitGitChanged(workspaceId: string): void {
  if (state?.gitDebounceTimer) clearTimeout(state.gitDebounceTimer);
  state!.gitDebounceTimer = setTimeout(() => {
    state!.gitDebounceTimer = null;
    send?.(IPC.WORKSPACE_GIT_CHANGED, { workspaceId });
  }, GIT_DEBOUNCE_MS);
}

function pollGit(workspaceId: string, workspacePath: string): void {
  if (!state) return;
  runGitStatus(workspacePath)
    .then((out) => {

      }
    );
    state!.fileWatcher = watcher;
  } catch {
    // ignore
  }
}

function emitGitChanged(workspaceId: string): void {
  if (state?.gitDebounceTimer) clearTimeout(state.gitDebounceTimer);
  state!.gitDebounceTimer = setTimeout(() => {
    state!.gitDebounceTimer = null;
    send?.(IPC.WORKSPACE_GIT_CHANGED, { workspaceId });
  }, GIT_DEBOUNCE_MS);
}

function pollGit(workspaceId: string, workspacePath: string): void {
  if (!state) return;
  runGitStatus(workspacePath)
    .then((out) => {
      if (state?.lastGitStatus !== out) {
        state.lastGitStatus = out;
        send?.(IPC.WORKSPACE_GIT_CHANGED, { workspaceId });
      }
    })
    .catch(() => {});
}

function startGitIndexWatcher(workspaceId: string, workspacePath: string): void {
  const gitDir = path.join(workspacePath, ".git");
  if (!existsSync(gitDir)) return;
  try {
    const watcher = watch(gitDir, { recursive: false }, (_eventType, filename) => {
      if (!filename) return;
      const f = filename as string;
      // index changes = staging/unstaging; HEAD changes = commits/checkouts
      if (f === "index" || f === "HEAD" || f === "COMMIT_EDITMSG") {
        emitGitChanged(workspaceId);
      }
    });
    state!.gitIndexWatcher = watcher;
  } catch {
    // ignore — git dir may not exist for non-git repos
  }
}

function startGitPoller(workspaceId: string, workspacePath: string): void {
  if (!existsSync(workspacePath)) return;
  state!.lastGitStatus = null;
  state!.gitPollTimer = setInterval(() => {
    pollGit(workspaceId, workspacePath);
  }, GIT_POLL_INTERVAL_MS);
}

export function initWorkspaceEvents(sendFn: Send): void {
  send = sendFn;
}

export function setActiveWorkspace(workspaceId: string, workspacePath: string): void {
  stopFileWatcher();
  stopGitIndexWatcher();
  stopGitPoller();
  state = {
    workspaceId,
    workspacePath,
    fileWatcher: null,
    fileDebounceTimer: null,
    gitIndexWatcher: null,
    gitDebounceTimer: null,
    gitPollTimer: null,
    lastGitStatus: null,
  };
  startFileWatcher(workspaceId, workspacePath);
  startGitIndexWatcher(workspaceId, workspacePath);
  startGitPoller(workspaceId, workspacePath);
}

export function clearActiveWorkspace(): void {
  stopFileWatcher();
  stopGitIndexWatcher();
  stopGitPoller();
  state = null;
}

export function getActiveWorkspaceId(): string | null {
  return state?.workspaceId ?? null;
}

import type { Workspace } from "@agentide/shared";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { mkdirSync } from "node:fs";
import path from "node:path";
import { ulid } from "ulid";
import { app } from "electron";
import { gitService } from "./git-service";

const getStoragePath = (): string => {
  const userData = app.getPath("userData");
  const dir = path.join(userData, "agentide");
  if (!existsSync(dir)) {
    mkdirSync(dir, { recursive: true });
  }
  return path.join(dir, "workspaces.json");
};

class WorkspaceManager {
  private workspaces: Map<string, Workspace> = new Map();
  private loaded = false;

  private loadFromDisk(): void {
    if (this.loaded) return;
    this.loaded = true;
    try {
      const filePath = getStoragePath();
      if (!existsSync(filePath)) return;
      const raw = readFileSync(filePath, "utf-8");
      const data = JSON.parse(raw) as { workspaces: Workspace[] };
      if (Array.isArray(data?.workspaces)) {
        for (const w of data.workspaces) {
          if (w?.id && w?.name != null && w?.path) {
            this.workspaces.set(w.id, {
              id: w.id,
              name: w.name,
              path: w.path,
              createdAt: w.createdAt ?? Date.now(),
              branch: w.branch,
              activeSessionId: w.activeSessionId,
            });
          }
        }
      }
    } catch {
      // ignore
    }
  }

  private saveToDisk(): void {
    try {
      const workspaces = Array.from(this.workspaces.values());
      writeFileSync(
        getStoragePath(),
        JSON.stringify({ workspaces }, null, 0),
        "utf-8"
      );
    } catch {
      // ignore
    }
  }

  list(): Workspace[] {
    this.loadFromDisk();
    return Array.from(this.workspaces.values()).sort((a, b) => b.createdAt - a.createdAt);
  }

  get(id: string): Workspace | undefined {
    this.loadFromDisk();
    return this.workspaces.get(id);
  }

  async create(name: string, path: string): Promise<Workspace> {
    this.loadFromDisk();
    if (!existsSync(path)) {
      throw new Error(`Directory does not exist: ${path}`);
    }

    // Check if it's a git repository and get the current branch
    let branch: string | undefined;
    try {
      const isGitRepo = await gitService.isGitRepository(path);
      if (isGitRepo) {
        branch = (await gitService.getCurrentBranch(path)) || undefined;
      }
    } catch {
      // Ignore git errors
    }

    const workspace: Workspace = {
      id: ulid(),
      name,
      path,
      createdAt: Date.now(),
      branch,
    };

    this.workspaces.set(workspace.id, workspace);
    this.saveToDisk();
    return workspace;
  }

  remove(id: string): void {
    this.loadFromDisk();
    if (!this.workspaces.has(id)) {
      throw new Error(`Workspace not found: ${id}`);
    }
    this.workspaces.delete(id);
    this.saveToDisk();
  }

  update(id: string, updates: Partial<Pick<Workspace, "name" | "branch" | "activeSessionId">>): Workspace {
    this.loadFromDisk();
    const workspace = this.workspaces.get(id);
    if (!workspace) {
      throw new Error(`Workspace not found: ${id}`);
    }

    const updated = { ...workspace, ...updates };
    this.workspaces.set(id, updated);
    this.saveToDisk();

  remove(id: string): void {
    this.loadFromDisk();
    if (!this.workspaces.has(id)) {
      throw new Error(`Workspace not found: ${id}`);
    }
    this.workspaces.delete(id);
    this.saveToDisk();
  }

  update(id: string, updates: Partial<Pick<Workspace, "name" | "branch" | "activeSessionId">>): Workspace {
    this.loadFromDisk();
    const workspace = this.workspaces.get(id);
    if (!workspace) {
      throw new Error(`Workspace not found: ${id}`);
    }

    const updated = { ...workspace, ...updates };
    this.workspaces.set(id, updated);
    this.saveToDisk();
    return updated;
  }

  async refreshGitInfo(id: string): Promise<Workspace> {
    this.loadFromDisk();
    const workspace = this.workspaces.get(id);
    if (!workspace) {
      throw new Error(`Workspace not found: ${id}`);
    }

    try {
      const isGitRepo = await gitService.isGitRepository(workspace.path);
      if (isGitRepo) {
        const currentBranch = await gitService.getCurrentBranch(workspace.path);
        return this.update(id, { branch: currentBranch || undefined });
      } else {
        return this.update(id, { branch: undefined });
      }
    } catch (error) {
      throw new Error(`Failed to refresh git info: ${error instanceof Error ? error.message : "Unknown error"}`);
    }
  }

  async getGitBranches(id: string): Promise<import("./git-service").GitBranch[]> {
    this.loadFromDisk();
    const workspace = this.workspaces.get(id);
    if (!workspace) {
      throw new Error(`Workspace not found: ${id}`);
    }

    try {
      const isGitRepo = await gitService.isGitRepository(workspace.path);
      if (!isGitRepo) {
        throw new Error("Not a git repository");
      }

      return await gitService.getAllBranches(workspace.path);
    } catch (error) {
      throw new Error(`Failed to get git branches: ${error instanceof Error ? error.message : "Unknown error"}`);
    }
  }

  async switchGitBranch(id: string, branchName: string): Promise<Workspace> {
    this.loadFromDisk();
    const workspace = this.workspaces.get(id);
    if (!workspace) {
      throw new Error(`Workspace not found: ${id}`);
    }

    try {
      const isGitRepo = await gitService.isGitRepository(workspace.path);
      if (!isGitRepo) {
        throw new Error("Not a git repository");
      }

      await gitService.switchBranch(workspace.path, branchName);
      return this.update(id, { branch: branchName });
    } catch (error) {
      throw new Error(`Failed to switch branch: ${error instanceof Error ? error.message : "Unknown error"}`);
    }
  }

  async createGitBranch(id: string, branchName: string): Promise<Workspace> {
    this.loadFromDisk();
    const workspace = this.workspaces.get(id);
    if (!workspace) {
      throw new Error(`Workspace not found: ${id}`);
    }

    try {
      const isGitRepo = await gitService.isGitRepository(workspace.path);
      if (!isGitRepo) {
        throw new Error("Not a git repository");
      }

      await gitService.createAndSwitchBranch(workspace.path, branchName);
      return this.update(id, { branch: branchName });
    } catch (error) {
      throw new Error(`Failed to create branch: ${error instanceof Error ? error.message : "Unknown error"}`);
    }
  }
}

