export const getCheckpointForMessage = (
  thread: ChatThread | null | undefined,
  messageIndex: number
): Checkpoint | undefined =>
  thread?.checkpoints?.find((c) => c?.messageIndex === messageIndex);

export const isCodeRestoreAvailable = (checkpoint: Checkpoint | undefined): boolean =>
  !!(checkpoint?.modifiedFiles?.length || checkpoint?.gitStashRef);

export const isMessageRewindable = (
  thread: ChatThread | null | undefined,
  messageIndex: number
): boolean => !!getCheckpointForMessage(thread, messageIndex);

import type { ImageAttachment } from "@agentide/shared";

// Supported image formats as per Claude Code documentation
const SUPPORTED_IMAGE_TYPES = [
  "image/jpeg",
  "image/jpg",
  "image/png",
  "image/gif",
  "image/webp"
];

const MAX_FILE_SIZE = 32 * 1024 * 1024; // 32MB total limit
const MAX_SINGLE_FILE_SIZE = 30 * 1024 * 1024; // 30MB per image
const MAX_IMAGES_PER_REQUEST = 100;

export const isImageFile = (file: File): boolean => {
  return SUPPORTED_IMAGE_TYPES.includes(file.type.toLowerCase());
};

export const validateImageFile = (file: File): { valid: boolean; error?: string } => {
  if (!isImageFile(file)) {
    return {
      valid: false,
      error: `Unsupported image format. Supported formats: ${SUPPORTED_IMAGE_TYPES.join(', ')}`
    };
  }

  if (file.size > MAX_SINGLE_FILE_SIZE) {
    return {
      valid: false,
      error: `Image file size must be less than 30MB. Current size: ${(file.size / 1024 / 1024).toFixed(2)}MB`
    };
  }

  return { valid: true };
};

export const validateImageAttachments = (attachments: ImageAttachment[]): { valid: boolean; error?: string } => {
  if (attachments.length > MAX_IMAGES_PER_REQUEST) {
    return {
      valid: false,
      error: `Too many images. Maximum ${MAX_IMAGES_PER_REQUEST} images per message.`
    };
  }

  const totalSize = attachments.reduce((sum, attachment) => sum + attachment.size, 0);
  if (totalSize > MAX_FILE_SIZE) {
    return {
      valid: false,
      error: `Total image size must be less than 32MB. Current total: ${(totalSize / 1024 / 1024).toFixed(2)}MB`
    };
  }

  return { valid: true };
};

export const fileToImageAttachment = (file: File): Promise<ImageAttachment> => {
  return new Promise((resolve, reject) => {
    const validation = validateImageFile(file);
    if (!validation.valid) {
      reject(new Error(validation.error));
      return;
    }

    const reader = new FileReader();
    reader.onload = (event) => {
      const dataUrl = event.target?.result as string;
      if (!dataUrl) {
        reject(new Error('Failed to read image file'));
        return;
      }

      const attachment: ImageAttachment = {
        id: crypto.randomUUID(),
        name: file.name,
        size: file.size,
        type: file.type,
        dataUrl,
        file
      };

      resolve(attachment);
    };

    reader.onerror = () => {
      reject(new Error('Failed to read image file'));
    };

    reader.readAsDataURL(file);
  });
};

export const filesToImageAttachments = async (files: FileList | File[]): Promise<ImageAttachment[]> => {
  const fileArray = Array.from(files);
  const imageFiles = fileArray.filter(isImageFile);

  if (imageFiles.length === 0) {
    throw new Error('No valid image files found');
  }

  const attachmentPromises = imageFiles.map(fileToImageAttachment);
  const attachments = await Promise.all(attachmentPromises);

  const validation = validateImageAttachments(attachments);
  if (!validation.valid) {
    throw new Error(validation.error);
  }

  return attachments;
};

export const getImageDimensions = (file: File): Promise<{ width: number; height: number }> => {
  return new Promise((resolve, reject) => {
    const img = new Image();
    const url = URL.createObjectURL(file);

    img.onload = () => {
      URL.revokeObjectURL(url);
      resolve({ width: img.naturalWidth, height: img.naturalHeight });
    };

  const attachmentPromises = imageFiles.map(fileToImageAttachment);
  const attachments = await Promise.all(attachmentPromises);

  const validation = validateImageAttachments(attachments);
  if (!validation.valid) {
    throw new Error(validation.error);
  }

  return attachments;
};

export const getImageDimensions = (file: File): Promise<{ width: number; height: number }> => {
  return new Promise((resolve, reject) => {
    const img = new Image();
    const url = URL.createObjectURL(file);

    img.onload = () => {
      URL.revokeObjectURL(url);
      resolve({ width: img.naturalWidth, height: img.naturalHeight });
    };

    img.onerror = () => {
      URL.revokeObjectURL(url);
      reject(new Error('Failed to load image'));
    };

    img.src = url;
  });
};

export const createImagePreviewUrl = (attachment: ImageAttachment): string => {
  return attachment.dataUrl;
};

export const revokeImagePreviewUrl = (url: string): void => {
  // For data URLs, no cleanup needed
  // This function is provided for API consistency
  if (url.startsWith('blob:')) {
    URL.revokeObjectURL(url);
  }
};

function unescapeHtml(html: string): string {
  return html
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&amp;/g, "&")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'");
}

type FileContextMention = {
  filePath: string;
  code: string;
  startLine: number;
  endLine: number;
  comment?: string;
};

function tryParseFileContextMention(id: string): FileContextMention | null {
  try {
    const parsed = JSON.parse(id);
    if (
      typeof parsed === "object" &&
      parsed !== null &&
      typeof parsed.filePath === "string" &&
      typeof parsed.code === "string"
    ) {
      return parsed as FileContextMention;
    }
  } catch {
    /* not a JSON file-context mention */
  }
  return null;
}

function formatFileContextBlock(ctx: FileContextMention): string {
  const lineRange =
    ctx.startLine === ctx.endLine
      ? `L${ctx.startLine}`
      : `L${ctx.startLine}-${ctx.endLine}`;
  const parts = [`\n<file_context path="${ctx.filePath}" lines="${lineRange}">`];
  parts.push("```");
  parts.push(ctx.code);
  parts.push("```");
  if (ctx.comment) {
    parts.push(`Note: ${ctx.comment}`);
  }
  parts.push("</file_context>\n");
  return parts.join("\n");
}

export function normalizeUserMessageContentToText(content: string): string {
  const trimmed = content.trim();
  if (!trimmed) return "";
  const unescaped = unescapeHtml(trimmed);
  const looksLikeHtml = /<[^>]+>/.test(unescaped) && /data-type\s*=\s*["']mention["']/.test(unescaped);
  if (!looksLikeHtml) return trimmed;
  try {
    const doc = new DOMParser().parseFromString(unescaped, "text/html");
    const parts: string[] = [];
    const walk = (node: Node) => {
      if (node.nodeType === Node.TEXT_NODE && node.textContent) {
        parts.push(node.textContent);
        return;
      }
      if (node.nodeType !== Node.ELEMENT_NODE) return;
      const el = node as Element;
      if (el.getAttribute?.("data-type") === "mention") {
        const idAttr = el.getAttribute("data-id") ?? "";
        const fileCtx = tryParseFileContextMention(idAttr);
        if (fileCtx) {
          parts.push(formatFileContextBlock(fileCtx));
          return;
        }
        const labelAttr = el.getAttribute("data-label");
        const raw = labelAttr || el.textContent?.trim() || idAttr || "@";
        const label = raw.trim();
        parts.push(label.startsWith("@") ? label : `@${label}`);
        return;
      }
      for (const child of el.childNodes) walk(child);
    };
    walk(doc.body);
    if (parts.length === 0) {
      return unescaped.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim() || trimmed;
    }
    return parts.join("");
  } catch {
    return unescaped.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim() || trimmed;
  }
}

