              ...ws,
              threads: ws.threads.map((t) =>
                t.id === threadId
                  ? {
                      ...t,
                      checkpoints: (t.checkpoints ?? []).map((c) =>
                        c.id === checkpointId
                          ? { ...c, modifiedFiles, createdFiles }
                          : c
                      ),
                    }
                  : t
              ),
            },
          },
        };
      });
    }).catch(() => {});
  }
},

