import { useEffect } from "react";
import { useWorkspaceStore } from "@/store/workspace.store";
import { useAgentStore } from "@/store/agent.store";
import { useUIStore } from "@/store/ui.store";
import { getElectronAPI } from "@/lib/electron";

export function useAppLayout() {
  const activeWorkspace = useWorkspaceStore((s) =>
    s.workspaces.find((w) => w.id === s.activeWorkspaceId) ?? null
  );
  const activeWorkspaceId = useWorkspaceStore((s) => s.activeWorkspaceId);
  const initAgentListeners = useAgentStore((s) => s.initListeners);
  const teardownAgentListeners = useAgentStore((s) => s.teardownListeners);
  const pendingToolApprovals = useAgentStore((s) => s.pendingToolApprovals);
  const leftPanelOpen = useUIStore((s) => s.leftPanelOpen);
  const rightPanelOpen = useUIStore((s) => s.rightPanelOpen);
  const activeView = useUIStore((s) => s.activeView);
  const setActiveView = useUIStore((s) => s.setActiveView);
  const centerPage = useUIStore((s) => s.centerPage);
  const secondaryPane = useUIStore((s) => s.secondaryPane);
  const openFileViewer = useUIStore((s) => s.openFileViewer);
  const setSecondaryPaneOpen = useUIStore((s) => s.setSecondaryPaneOpen);
  const setWebViewOpen = useUIStore((s) => s.setWebViewOpen);
  const webView = useUIStore((s) => s.webView);
  const apiKeyDialogOpen = useUIStore((s) => s.apiKeyDialogOpen);
  const setApiKeyDialogOpen = useUIStore((s) => s.setApiKeyDialogOpen);
  const checkApiKey = useUIStore((s) => s.checkApiKey);
  const hasApiKey = useUIStore((s) => s.hasApiKey);
  const agentLogDrawerOpen = useUIStore((s) => s.agentLogDrawerOpen);
  const setAgentLogDrawerOpen = useUIStore((s) => s.setAgentLogDrawerOpen);

  useEffect(() => {
    checkApiKey();
  }, [checkApiKey]);

  useEffect(() => {
    initAgentListeners();
    return () => teardownAgentListeners();
  }, [initAgentListeners, teardownAgentListeners]);

  useEffect(() => {
    if (activeWorkspaceId) {
      useAgentStore.getState().loadWorkspace(activeWorkspaceId);
    }
  }, [activeWorkspaceId]);

  useEffect(() => {
    const api = getElectronAPI();
    if (!api?.workspace?.onFilesChanged || !api?.workspace?.onGitChanged) return;
    const unsubFiles = api.workspace.onFilesChanged((payload) => {
      useWorkspaceStore.getState().notifyFilesChanged(payload.workspaceId);
    });
    const unsubGit = api.workspace.onGitChanged((payload) => {
      useWorkspaceStore.getState().notifyGitChanged(payload.workspaceId);
      if (payload.workspaceId === useWorkspaceStore.getState().activeWorkspaceId) {
        useWorkspaceStore.getState().refreshGitInfo(payload.workspaceId);
      }
    });
    return () => {
      unsubFiles();
      unsubGit();
    };
  }, []);

  const hasSecondaryPane = secondaryPane.open;
  const globalPendingApproval =
    (activeWorkspaceId ? pendingToolApprovals[activeWorkspaceId] : null) ??
    Object.values(pendingToolApprovals).find((a) => a != null) ??
    null;

  return {
    activeWorkspace,
    activeWorkspaceId,
    leftPanelOpen,
    rightPanelOpen,
    activeView,
    setActiveView,
    centerPage,
    secondaryPane,
    hasSecondaryPane,
    openFileViewer,
    setSecondaryPaneOpen,
    setWebViewOpen,
    webView,
    apiKeyDialogOpen,
    setApiKeyDialogOpen,
    checkApiKey,
    hasApiKey,
    agentLogDrawerOpen,
    setAgentLogDrawerOpen,
    globalPendingApproval,
  };
}

import { useEffect, useState } from "react";
import type { AgentSkillItem } from "@agentide/shared";
import { getElectronAPI } from "@/lib/electron";

export function useAgentSkills(): AgentSkillItem[] {
  const [skills, setSkills] = useState<AgentSkillItem[]>([]);

  useEffect(() => {
    const api = getElectronAPI();
    if (!api?.skills) {
      setSkills([]);
      return;
    }
    let cancelled = false;
    api.skills.list().then((res) => {
      if (cancelled) return;
      if (res.success && res.data) setSkills(res.data);
      else setSkills([]);
    });
    return () => {
      cancelled = true;
    };
  }, []);

  return skills;
}

import { useCallback } from "react";
import type { Editor } from "@tiptap/react";
import { useAgentSkills } from "./use-agent-skills";

export function useSkillHint() {
  const agentSkills = useAgentSkills();

  const extractMentionedSkillNames = useCallback(
    (editor: Editor | null): string[] => {
      if (!editor) return [];
      const json = editor.getJSON();
      if (!json) return [];
      const skillMap = new Map(agentSkills.map((s) => [s.id, s.name]));
      const names: string[] = [];
      const walk = (node: Record<string, unknown>) => {
        if (node.type === "mention") {
          const id = (node.attrs as Record<string, string> | undefined)?.id;
          if (id && skillMap.has(id)) names.push(skillMap.get(id)!);
        }
        if (Array.isArray(node.content)) {
          for (const child of node.content) walk(child as Record<string, unknown>);
        }
      };
      walk(json as Record<string, unknown>);
      return [...new Set(names)];
    },
    [agentSkills]
  );

  const withSkillHint = useCallback(
    (text: string, skills: string[]): string => {
      if (skills.length === 0) return text;
      const hint = skills.length === 1
        ? `Use the "${skills[0]}" skill.`
        : `Use these skills: ${skills.map((n) => `"${n}"`).join(", ")}.`;
      return `${hint}\n\n${text}`;
    },
    []
  );

  const augmentWithSkillHint = useCallback(
    (editor: Editor | null, text: string): string => {
      const skillNames = extractMentionedSkillNames(editor);
      return withSkillHint(text, skillNames);
    },
    [extractMentionedSkillNames, withSkillHint]
  );

  return {
    extractMentionedSkillNames,
    withSkillHint,
    augmentWithSkillHint,
  };
}

import { useMemo } from "react";
import type { AgentMessage } from "@agentide/shared";

export type ThreadChangedFile = {
  path: string;
  added: number;
  deleted: number;
};

const MUTATING_TOOL_NAMES = new Set([
  "applypatch",
  "edit",
  "multiedit",
  "write",
  "delete",
  "editnotebook",
  "createfile",
  "rename",
  "move",
  "copy",
  "text_editor",
  "str_replace_editor",
]);

function normalizeWorkspacePath(path: string, workspacePath: string | null): string {
  const normalized = path.replace(/\\/g, "/").trim();
  if (!workspacePath) return normalized;
  const workspaceNormalized = workspacePath.replace(/\\/g, "/").replace(/\/+$/, "");
  if (normalized.startsWith(`${workspaceNormalized}/`)) {
    return normalized.slice(workspaceNormalized.length + 1);
  }
  return normalized;
}

function countLines(text: string): number {
  if (!text) return 0;
  return text.split(/\r?\n/).length;
}

function extractPatchPaths(input: unknown): string[] {
  const source = typeof input === "string" ? input : typeof input === "object" && input ? JSON.stringify(input) : "";
  if (!source) return [];
  const matches = [...source.matchAll(/\*\*\* (?:Add|Update) File: (.+)/g)];
  return matches.map((m) => m[1].trim()).filter(Boolean);
}

function extractPatchStats(input: unknown): ThreadChangedFile[] {
  const source = typeof input === "string" ? input : typeof input === "object" && input ? JSON.stringify(input) : "";
  if (!source) return [];
  const rows = source.split(/\r?\n/);
  const byFile = new Map<string, ThreadChangedFile>();
  let currentPath = "";

  for (const row of rows) {
    const header = row.match(/^\*\*\* (?:Add|Update) File: (.+)$/);
    if (header) {
      currentPath = header[1].trim();
      if (!byFile.has(currentPath)) {
        byFile.set(currentPath, { path: currentPath, added: 0, deleted: 0 });
      }
      continue;
    }
    if (!currentPath) continue;
    if (row.startsWith("+") && !row.startsWith("+++")) {
      byFile.get(currentPath)!.added += 1;
      continue;
    }
    if (row.startsWith("-") && !row.startsWith("---")) {
      byFile.get(currentPath)!.deleted += 1;
    }
  }

  return [...byFile.values()];
}

function extractEditStats(input: unknown): ThreadChangedFile[] {
  if (!input || typeof input !== "object" || Array.isArray(input)) return [];
  const obj = input as Record<string, unknown>;
  const path = [
    obj.path,
    obj.file_path,
    obj.filepath,
    obj.target_file,
    obj.target_notebook,
  ].find((value): value is string => typeof value === "string" && value.trim().length > 0);

  if (!path) return [];

  const oldText = typeof obj.old_str === "string"
    ? obj.old_str
    : typeof obj.old_string === "string"
      ? obj.old_string
      : "";
  const newText = typeof obj.new_str === "string"
    ? obj.new_str
    : typeof obj.new_string === "string"
      ? obj.new_string
      : "";

  return [{
    path,
    added: countLines(newText),
    deleted: countLines(oldText),
  }];
}

function extractPathsFromInput(input: unknown): string[] {
  const found = new Set<string>();
  const visit = (value: unknown): void => {
    if (!value) return;
    if (typeof value === "string") return;
    if (Array.isArray(value)) {
      value.forEach(visit);
      return;
    }
    if (typeof value === "object") {
