function extractPathsFromInput(input: unknown): string[] {
  const found = new Set<string>();
  const visit = (value: unknown): void => {
    if (!value) return;
    if (typeof value === "string") return;
    if (Array.isArray(value)) {
      value.forEach(visit);
      return;
    }
    if (typeof value === "object") {
      for (const [key, child] of Object.entries(value as Record<string, unknown>)) {
        const keyLower = key.toLowerCase();
        if (
          typeof child === "string" &&
          (keyLower === "path" ||
            keyLower === "filepath" ||
            keyLower === "file_path" ||
            keyLower === "target_file" ||
            keyLower === "target_notebook" ||
            keyLower === "new_path" ||
            keyLower === "old_path")
        ) {
          const cleaned = child.trim();
          if (cleaned) found.add(cleaned);
        }
        visit(child);
      }
    }
  };
  visit(input);
  return [...found];
}

export function useThreadChangedFiles(
  messages: AgentMessage[],
  workspacePath: string | null
): ThreadChangedFile[] {
  return useMemo(() => {
    const ordered = new Map<string, ThreadChangedFile>();
    for (const message of messages) {
      if (message.role !== "tool" || !message.toolName) continue;
      const toolName = message.toolName.toLowerCase();
      const stats: ThreadChangedFile[] =
        toolName === "applypatch"
          ? extractPatchStats(message.toolInput)
          : toolName === "edit" || toolName === "multiedit" || toolName === "editnotebook"
            ? extractEditStats(message.toolInput)
            : MUTATING_TOOL_NAMES.has(toolName)
              ? extractPathsFromInput(message.toolInput).map((path) => ({
                  path,
                  added: 0,
                  deleted: 0,
                }))
              : [];

      for (const stat of stats) {
        const normalized = normalizeWorkspacePath(stat.path, workspacePath);
        if (!normalized) continue;
        const prev = ordered.get(normalized);
        if (prev) {
          ordered.set(normalized, {
            path: normalized,
            added: prev.added + stat.added,
            deleted: prev.deleted + stat.deleted,
          });
        } else {
          ordered.set(normalized, {
            path: normalized,
            added: stat.added,
            deleted: stat.deleted,
          });
        }
      }
    }
    return [...ordered.values()];
  }, [messages, workspacePath]);
}

import { useEffect, useMemo, useState } from "react";
import type { FileTreeNode } from "@agentide/shared";
import { getElectronAPI } from "@/lib/electron";
import { useWorkspaceStore } from "@/store/workspace.store";

function flattenBreadthFirst(
  tree: FileTreeNode,
  rootPath: string,
): { id: string; label: string; type: "file" | "directory" }[] {
  const files: { id: string; label: string; type: "file" | "directory" }[] = [];
  const dirs: { id: string; label: string; type: "file" | "directory" }[] = [];
  const queue: FileTreeNode[] = [tree];

  while (queue.length > 0) {
    const node = queue.shift()!;
    const relativePath = node.path.startsWith(rootPath)
      ? node.path.slice(rootPath.length).replace(/^\//, "")
      : node.name;

    if (relativePath) {
      const item = { id: node.path, label: relativePath, type: node.type };
      if (node.type === "file") files.push(item);
      else dirs.push(item);
    }

    if (node.children) {
      queue.push(...node.children);
    }
  }

  return [...files, ...dirs];
}

export function useWorkspaceFiles(): { id: string; label: string; type: "file" | "directory" }[] {
  const activeWorkspace = useWorkspaceStore((s) =>
    s.workspaces.find((w) => w.id === s.activeWorkspaceId) ?? null
  );
  const fileTreeVersion = useWorkspaceStore((s) =>
    activeWorkspace?.id ? (s.fileTreeVersions[activeWorkspace.id] ?? 0) : 0
  );
  const [fullTree, setFullTree] = useState<FileTreeNode | null>(null);

  useEffect(() => {
    if (!activeWorkspace?.path) {
      setFullTree(null);
      return;
    }
    const api = getElectronAPI();
    if (!api) {
      setFullTree(null);
      return;
    }
    api.filesystem.readDirectoryTree(activeWorkspace.path).then((res) => {
      if (res.success && res.data) {
        setFullTree(res.data);
      } else {
        setFullTree(null);
      }
    });
  }, [activeWorkspace?.path, fileTreeVersion]);

  return useMemo(() => {
    if (!fullTree || !activeWorkspace?.path) return [];
    return flattenBreadthFirst(fullTree, activeWorkspace.path);
  }, [fullTree, activeWorkspace?.path]);
}

