function filterLogLines(content: string, source: LogSourceFilter): string {
  if (!content.trim()) return content;
  if (source === "all") return content;
  const tag = ` [${source}] `;
  return content
    .split("\n")
    .filter((line) => line.includes(tag))
    .join("\n");
}

