              ) : (
                <GroupedFileList
                  files={unstaged}
                  onSelect={handleFileSelect}
                  selectedPath={selectedPath}
                  action="stage"
                  onAction={handleStage}
                  actionLoadingPath={stageLoading}
                  onRevert={handleRevert}
