function getUniqueSelector(element) {
  if (element.id) {
    return '#' + CSS.escape(element.id);
  }

  const path = [];
  let current = element;

  while (current && current.nodeType === Node.ELEMENT_NODE) {
    let selector = current.tagName.toLowerCase();

    if (current.id) {
      selector = '#' + CSS.escape(current.id);
      path.unshift(selector);
      break;
    }

    if (current.className && typeof current.className === 'string') {
      const classes = current.className.trim().split(/\\s+/).filter(c => c && !c.startsWith('__agentide'));
      if (classes.length > 0) {
        selector += '.' + classes.slice(0, 2).map(c => CSS.escape(c)).join('.');
      }
    }

    const parent = current.parentElement;
    if (parent) {
      const siblings = Array.from(parent.children).filter(
        el => el.tagName === current.tagName
      );
      if (siblings.length > 1) {
        const index = siblings.indexOf(current) + 1;
        selector += ':nth-of-type(' + index + ')';
      }
    }

    path.unshift(selector);
    current = parent;

    if (path.length > 4) break;
  }

  return path.join(' > ');
}

function getElementInfo(element) {
  const tagName = element.tagName.toLowerCase();
  const id = element.id || null;
  const classList = element.className && typeof element.className === 'string' 
    ? element.className.trim().split(/\\s+/).filter(c => c && !c.startsWith('__agentide'))
    : [];
  const rect = element.getBoundingClientRect();
  const selector = getUniqueSelector(element);
  const reactComponent = getReactComponentName(element);
  const reactProps = getReactProps(element);
  const reactSource = getReactSource(element);

  const computedStyle = window.getComputedStyle(element);
  const styles = {
    display: computedStyle.display,
    position: computedStyle.position,
    fontSize: computedStyle.fontSize,
    color: computedStyle.color,
    backgroundColor: computedStyle.backgroundColor,
  };

  const attributes = {};
  for (const attr of element.attributes) {
    if (!attr.name.startsWith('__react')) {
      attributes[attr.name] = attr.value;
    }
  }

  return {
    tagName,
    id,
    classList,
    selector,
    rect: {
      x: Math.round(rect.x),
      y: Math.round(rect.y),
      width: Math.round(rect.width),
      height: Math.round(rect.height),
    },
    attributes,
    styles,
    textContent: element.textContent?.slice(0, 100)?.trim() || null,
    react: {
      component: reactComponent,
      props: reactProps ? Object.keys(reactProps).filter(k => !k.startsWith('__')) : null,
      source: reactSource,
    },
  };
}

function updateTooltip(element, x, y) {
