              <Label>Directory</Label>
              <div className="flex gap-2">
                <Input
                  type="text"
                  value={path}
                  onChange={(e) => setPath(e.target.value)}
                  placeholder={
                    hasFolderPicker
                      ? "Select a folder or paste path"
                      : "/Users/you/projects/my-project"
                  }
                />
                {hasFolderPicker && (
                  <Button type="button" variant="secondary" onClick={handleSelectFolder}>
                    Browse…
                  </Button>
                )}
