              {path.trim() && (
                <p className="text-xs text-muted-foreground">
                  Project name: {getProjectNameFromPath(path)}
                </p>
              )}
            </div>
          )}

          {step === 2 && mode === "empty" && (
            <>
              <div className="flex flex-col gap-1.5">
                <Label>Parent directory</Label>
                <div className="flex gap-2">
                  <Input
                    type="text"
                    value={path}
                    onChange={(e) => setPath(e.target.value)}
                    placeholder={
                      hasFolderPicker ? "Select folder or paste path" : "/Users/you/projects"
                    }
                  />
                  {hasFolderPicker && (
                    <Button type="button" variant="secondary" onClick={handleSelectFolder}>
                      Browse…
                    </Button>
                  )}
                </div>
              </div>
              <div className="flex flex-col gap-1.5">
                <Label>Folder name</Label>
                <Input
                  type="text"
                  value={folderName}
                  onChange={(e) => setFolderName(e.target.value)}
                  placeholder="my-project"
                />
              </div>
            </>
          )}

          {step === 2 && mode === "clone" && (
            <>
              <div className="flex flex-col gap-1.5">
                <Label>Clone into (parent directory)</Label>
                <div className="flex gap-2">
                  <Input
                    type="text"
                    value={path}
                    onChange={(e) => setPath(e.target.value)}
                    placeholder={
                      hasFolderPicker ? "Select folder or paste path" : "/Users/you/projects"
                    }
                  />
                  {hasFolderPicker && (
                    <Button type="button" variant="secondary" onClick={handleSelectFolder}>
                      Browse…
                    </Button>
                  )}
                </div>
              </div>
              <div className="flex flex-col gap-1.5">
                <Label>Repository URL</Label>

