export function basename(path: string): string {
  const i = path.lastIndexOf("/");
  return i < 0 ? path : path.slice(i + 1);
}

export function parentDir(path: string): string | null {
  const i = path.lastIndexOf("/");
  return i > 0 ? path.slice(0, i + 1) : null;
}

