                  <span className="shrink-0 font-mono text-[10px] text-muted-foreground">
                    {d.line}:{d.col}
                  </span>
                  {d.source && (
                    <span className="shrink-0 rounded bg-muted px-1 text-[9px] font-medium text-muted-foreground">
                      {d.source}

