export type { EmbeddedToolbarProps };

export const EmbeddedToolbar = ({
  isRunning,
  canShowAttach,
  onAttachClick,
  isProcessingImages,
  canSubmit,
  imageCount,
  onStop,
  onSubmit,
}: EmbeddedToolbarProps) => {
  const selectedModel = useAgentStore((s) => s.selectedModel);
  const setSelectedModel = useAgentStore((s) => s.setSelectedModel);
  const modelOptions = useChatEditorStore((s) => s.modelOptions);

  const modelOptionsFormatted = modelOptions.map((m) => ({ value: m.value, label: m.label }));

  return (
    <div className="flex flex-wrap items-center gap-2 pb-2 px-2">
      <div className="flex flex-wrap items-center gap-2">
        <ModeSelector disabled={isRunning} />
        {canShowAttach && (
          <Button
            size="icon-xs"
            variant="ghost"
            onClick={onAttachClick}
            disabled={isRunning || isProcessingImages}
            title="Attach images"
          >
            <IconPaperclip stroke={1.5} className="size-4" />
          </Button>
        )}
      </div>

      <div className="ml-auto flex items-center gap-2">
        {modelOptionsFormatted.length > 0 && (
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="ghost" size="xs" disabled={isRunning}>
                <span className="truncate text-xs text-left">
                  {modelOptionsFormatted.find((o) => o.value === selectedModel)?.label ?? selectedModel}
                </span>
                <ChevronDownIcon className="size-4 shrink-0 opacity-50" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-[220px]">
              <DropdownMenuRadioGroup value={selectedModel} onValueChange={setSelectedModel}>
                {modelOptionsFormatted.map((opt) => (
                  <DropdownMenuRadioItem key={opt.value} value={opt.value}>
                    {opt.label}
                  </DropdownMenuRadioItem>
                ))}
              </DropdownMenuRadioGroup>
            </DropdownMenuContent>
          </DropdownMenu>
        )}

        {isRunning ? (
          <Button size="icon-sm" rounded="full" variant="secondary" onClick={onStop}>
            <StopIcon className="size-4" />
          </Button>
        ) : (
          <Button
            size="icon-sm"
            rounded="full"
            variant={canSubmit || imageCount > 0 ? "brand" : "secondary"}
            onClick={onSubmit}
            disabled={!canSubmit && imageCount === 0}
          >
            <ArrowUpIcon className="size-4" />
          </Button>
        )}
      </div>
    </div>
  );
};

import type { AgentMode } from "@agentide/shared";
import { cn } from "@/lib/cn";
import { useAgentStore } from "@/store/agent.store";
import { AGENT_MODES } from "./constants";

type ModeSelectorProps = {
  disabled?: boolean;
};

export const ModeSelector = ({ disabled }: ModeSelectorProps) => {
  const selectedMode = useAgentStore((s) => s.selectedMode);
  const setSelectedMode = useAgentStore((s) => s.setSelectedMode);
  return (
    <div
      role="tablist"
      aria-label="Agent mode"
      className="flex h-7 gap-1 rounded-lg bg-foreground/5 p-0.5"
    >
      {AGENT_MODES.map((mode) => {
        const Icon = mode.icon;
        const isSelected = selectedMode === mode.value;
        return (
          <button
            key={mode.value}
            type="button"
            role="tab"
            aria-selected={isSelected}
            title={`${mode.label}: ${mode.description}`}
            disabled={disabled}
            onClick={() => setSelectedMode(mode.value)}
            className={cn(
              "inline-flex size-6 shrink-0 items-center justify-center rounded-lg transition-all focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
              isSelected ? "bg-background/80 shadow-card" : "hover:bg-foreground/5"
            )}
          >
            <Icon className="size-3.5! shrink-0" />
          </button>
        );
      })}
    </div>
  );
};

import { Button, Popover, PopoverContent, PopoverTrigger } from "@agentide/ui";
import { useAgentStore } from "@/store/agent.store";
import { useWorkspaceStore } from "@/store/workspace.store";
import { IconChartBar } from "@tabler/icons-react";

const MODEL_CONTEXT_WINDOW: Record<string, number> = {
  "claude-sonnet-4-6": 200_000,
  "claude-opus-4-6": 200_000,
  "claude-haiku-4-5": 200_000,
  "claude-sonnet-4-20250514": 200_000,
  "gpt-5.2": 128_000,
  "gpt-5-mini": 128_000,
  "gpt-5.2-codex": 400_000,
  "gpt-5.3-codex": 400_000,
  "gpt-5.1-codex-mini": 400_000,
};

const DEFAULT_CONTEXT_WINDOW = 200_000;

function formatTokens(n: number): string {
  if (n >= 1000) return `${(n / 1000).toFixed(1)}k`;
  return n.toString();
}

export const TokenUsagePopover = () => {
  const activeWorkspaceId = useWorkspaceStore((s) => s.activeWorkspaceId);
  const getActiveThread = useAgentStore((s) => s.getActiveThread);
  const selectedModel = useAgentStore((s) => s.selectedModel);

  const activeThread = activeWorkspaceId ? getActiveThread(activeWorkspaceId) : null;
  const inputTokens = activeThread?.inputTokens ?? 0;
  const outputTokens = activeThread?.outputTokens ?? 0;
  const lastRunInput = activeThread?.lastRunInputTokens ?? 0;
  const lastRunOutput = activeThread?.lastRunOutputTokens ?? 0;

  const contextWindow = MODEL_CONTEXT_WINDOW[selectedModel] ?? DEFAULT_CONTEXT_WINDOW;
  const totalUsed = inputTokens + outputTokens;
  const estimatedRemaining = Math.max(0, contextWindow - lastRunInput);

  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button
          variant="ghost"
          size="xs"
          title="Token usage"
        >
          <IconChartBar stroke={1} className="size-3.5 shrink-0" />
          <span className="text-xxs">
            {formatTokens(totalUsed)} tokens
          </span>
        </Button>
      </PopoverTrigger>
      <PopoverContent align="end" side="top" className="w-64">
        <div className="space-y-3">
          <div className="text-sm font-medium text-foreground">Token usage (this thread)</div>
          <div className="grid grid-cols-2 gap-x-4 gap-y-1 text-xs text-muted-foreground">
            <span>Input</span>
            <span className="text-right font-mono">{formatTokens(inputTokens)}</span>
            <span>Output</span>
            <span className="text-right font-mono">{formatTokens(outputTokens)}</span>
            <span>Last run</span>
            <span className="text-right font-mono">
              {formatTokens(lastRunInput + lastRunOutput)}
            </span>
            <span>Context window</span>
            <span className="text-right font-mono">{formatTokens(contextWindow)}</span>
            <span>Est. remaining</span>
            <span className="text-right font-mono">{formatTokens(estimatedRemaining)}</span>
          </div>
        </div>
      </PopoverContent>
    </Popover>
  );
};

